/*--------------------
    * Smooth Scroll
----------------------*/
WEA.SmoothScroll = function() {
    $('.navbar-nav a[href^="#"]').on('click', function(e) {
        var target = $(this.getAttribute('href'));
        if (target.exists()) {
            e.preventDefault();
            $('html, body').stop().animate({
                scrollTop: target.offset().top - 70
            }, 800, 'swing');
        }
    });
}

/*--------------------
    * Back To Top
----------------------*/
WEA.BackToTop = function() {
    var btn = $('.back-to-top');
    if (btn.exists()) {
        $(window).on('scroll', function() {
            if ($(this).scrollTop() > 400) {
                btn.addClass('active');
            } else {
                btn.removeClass('active');
            }
        });
        btn.on('click', function() {
            $('html, body').animate({scrollTop: 0}, 800);
            return false;
        });
    }
}

/*--------------------
    * Counter
----------------------*/
WEA.Counter = function() {
    $('.counter').each(function() {
        var bottom_object = $(this).offset().top + $(this).outerHeight();
        var bottom_window = $(window).scrollTop() + $(window).height();
        if (bottom_window > bottom_object) {
            var $this = $(this),
                countTo = $this.attr('data-count');
            if (!$this.hasClass('counted')) {
                $this.addClass('counted');
                $({ countNum: $this.text() }).animate({
                    countNum: countTo
                }, {
                    duration: 2000,
                    easing: 'swing',
                    step: function() {
                        $this.text(Math.floor(this.countNum));
                    },
                    complete: function() {
                        $this.text(this.countNum);
                    }
                });
            }
        }
    });
}

/*--------------------
    * Preloader
----------------------*/
WEA.Preloader = function() {
    if ($('#preloader').exists()) {
        $(window).on('load', function() {
            $('#preloader').fadeOut('slow', function() {
                $(this).remove();
            });
        });
    }
}

/*--------------------
    * Contact Form
----------------------*/
WEA.ContactForm = function() {
    if ($('#contact-form').exists()) {
        $('#contact-form').on('submit', function(e) {
            e.preventDefault();
            var valid = true;
            $(this).find('input[required], textarea[required]').each(function() {
                if (!$(this).val().trim()) {
                    valid = false;
                    $(this).addClass('is-invalid');
                } else {
                    $(this).removeClass('is-invalid');
                }
            });
            if (valid) {
                $('.form-message').html('<div class="alert alert-success">Thank you for your message.</div>');
            }
        });
    }
}

