var SFGD = SFGD || {};

SFGD.eventFilter = {
    init: function() {
        this.cacheDom();
        this.bindEvents();
    },

    cacheDom: function() {
        this.$filters = $('.category-filter');
        this.$events = $('.event-card');
    },

    bindEvents: function() {
        this.$filters.on('click', this.applyFilter.bind(this));
    },

    applyFilter: function(e) {
        var category = $(e.target).data('category');
        this.$events.hide();
        if (category === 'all') {
            this.$events.show();
        } else {
            this.$events.filter('.' + category).show();
        }
    }
};

$(document).ready(function() {
    SFGD.eventFilter.init();
});

